  ('ENTERTAINMENT',             'Entertainment'),
  ('SERVICES',                  'Services'),
  ('GOVERNMENT_AND_NON_PROFIT', 'Community and government'),
  ('BANK_FEES',                 'Bank fees'),
  ('LOAN_PAYMENTS',             'Loan payments'),
  ('TRANSFER_IN',               'Internal transfer'),
  ('TRANSFER_OUT',              'Internal transfer')
) as m(provider_category, category_name)
join categories c on c.name = m.category_name and c.parent_id is not null;

insert into schema_migrations (filename) values ('004_seed_taxonomy.sql') on conflict do nothing;

-- ============================================================
-- 005_buckets.sql
-- ============================================================
-- Stage 3: zero based buckets, allocated each pay period.

-- One row, holding how often money arrives and a date we know a pay landed.
-- Everything else is derived from those two facts.
create table pay_cycle (
  id           boolean primary key default true check (id),
  cadence      text not null default 'fortnightly'
               check (cadence in ('weekly', 'fortnightly', 'monthly')),
  anchor_date  date not null,
  updated_at   timestamptz not null default now()
);

-- Generated from the cycle, so a period is a stable thing to hang allocations
-- and reports off.
create table pay_periods (
  id         uuid primary key default gen_random_uuid(),
  starts_on  date not null unique,
  ends_on    date not null,
  created_at timestamptz not null default now(),
  constraint pay_periods_ordered check (ends_on >= starts_on)
);

create index pay_periods_range_idx on pay_periods (starts_on, ends_on);

-- A bucket is a job for money: groceries, fuel, the power bill.
create table buckets (
  id          uuid primary key default gen_random_uuid(),
  name        text not null unique,
  -- What it is for, shown on the buckets page.
  notes       text,
  -- The usual amount to put in each period. Allocations default to this.
  target      numeric(12,2) not null default 0,
  -- Whether what is left over at the end of a period rolls into the next one.
  -- A bill you save up for wants this, a weekly spending allowance does not.
  carry_over  boolean not null default true,
  sort_order  integer not null default 100,
  archived    boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Which categories count as spending from a bucket. A bucket can cover several,
-- for example one Everyday bucket over groceries and merchandise.
create table bucket_categories (
  bucket_id   uuid not null references buckets (id) on delete cascade,
  category_id uuid not null references categories (id) on delete cascade,
  primary key (bucket_id, category_id),
  -- A category belongs to at most one bucket, otherwise spending is counted
  -- twice and the totals stop adding up.
  constraint bucket_categories_category_once unique (category_id)
);

-- What was actually put into a bucket for a period.
create table bucket_allocations (
  id            uuid primary key default gen_random_uuid(),
  bucket_id     uuid not null references buckets (id) on delete cascade,
  pay_period_id uuid not null references pay_periods (id) on delete cascade,
  allocated     numeric(12,2) not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (bucket_id, pay_period_id)
);

create index bucket_allocations_period_idx on bucket_allocations (pay_period_id);

insert into schema_migrations (filename) values ('005_buckets.sql') on conflict do nothing;

-- ============================================================
-- 006_budget_flows.sql
-- ============================================================
-- One definition of what counts as budget activity, so every stage agrees.
--
-- A transfer between two accounts we own is not spending: the money is still
-- ours. There is one exception. Money leaving a spendable account for a loan or
-- a mortgage really does leave our cash, and has to be budgeted for, so it
-- counts. Only the side that leaves the liquid account counts, otherwise the
-- same event would be counted twice.
create view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    not t.is_transfer
    or (coalesce(a.is_liquid, false) and not coalesce(pa.is_liquid, true))
  )                           as counts
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id;

insert into schema_migrations (filename) values ('006_budget_flows.sql') on conflict do nothing;

-- ============================================================
-- 007_expected_income.sql
-- ============================================================
-- A job change makes historical income a poor guide to future income, so the
-- forecast needs to be told what to expect rather than inferring it. Null means
-- fall back to what recent periods actually did.
alter table pay_cycle
  add column expected_income numeric(12,2);

insert into schema_migrations (filename) values ('007_expected_income.sql') on conflict do nothing;

-- ============================================================
-- 008_commitments.sql
-- ============================================================
-- Stage 4: recurring commitments, detected from history, used by the forecast.

create table commitments (
  id             uuid primary key default gen_random_uuid(),
  -- A stable key derived from the description, so re-running detection updates
  -- the same row rather than making a new one.
  match_key      text not null unique,
  label          text not null,
  category_id    uuid references categories (id) on delete set null,
  -- Negative, like every other outflow in this app.
  typical_amount numeric(12,2) not null,
  cadence_days   integer not null,
  occurrences    integer not null default 0,
  -- How regular the gaps are, 0 to 1. Detection only keeps the reliable ones.
  regularity     numeric(4,3) not null default 0,
  last_seen      date,
  next_due       date,
  -- Set by hand in the UI: a commitment we know about that history has not
  -- shown yet, or one we want the forecast to ignore.
  source         text not null default 'detected' check (source in ('detected', 'manual')),
  active         boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index commitments_next_due_idx on commitments (next_due) where active;

alter table sync_runs
  add column commitments_found integer not null default 0;

insert into schema_migrations (filename) values ('008_commitments.sql') on conflict do nothing;

-- ============================================================
-- 009_alerts.sql
-- ============================================================
-- Stage 5: email alerts.

-- One row of settings. Alerts are off until an address is set, so nothing is
-- ever sent by surprise.
create table alert_settings (
  id                        boolean primary key default true check (id),
  enabled                   boolean not null default false,
  email_to                  text,
  runway_days_threshold     integer not null default 21,
  large_transaction_amount  numeric(12,2) not null default 500.00,
  notify_bucket_overspend   boolean not null default true,
  notify_sync_failure       boolean not null default true,
  notify_unreviewed         boolean not null default true,
  updated_at                timestamptz not null default now()
);

insert into alert_settings (id) values (true);

-- Every alert considered, whether or not it was sent. The dedupe key is what
-- stops the same warning arriving twice a day: it only changes when the
-- situation meaningfully changes.
create table alert_log (
  id          uuid primary key default gen_random_uuid(),
  kind        text not null,
  dedupe_key  text not null,
  subject     text not null,
  body        text not null,
  status      text not null default 'pending'
              check (status in ('pending', 'sent', 'failed', 'skipped', 'suppressed')),
  error       text,
  created_at  timestamptz not null default now(),
  sent_at     timestamptz
);

create index alert_log_dedupe_idx on alert_log (kind, dedupe_key, created_at desc);
create index alert_log_created_idx on alert_log (created_at desc);

alter table sync_runs
  add column alerts_sent integer not null default 0;

insert into schema_migrations (filename) values ('009_alerts.sql') on conflict do nothing;

-- ============================================================
-- 010_analyst_and_manual_accounts.sql
-- ============================================================
-- Periodic analysis by Claude, and manual accounts for debts open banking
-- cannot see.

-- A credit card or personal loan we hold elsewhere is still part of the
-- picture, so it gets an account with no Redbark id and a balance entered by
-- hand. The roles list grows to name them.
alter table accounts drop constraint if exists accounts_role_check;
alter table accounts
  add constraint accounts_role_check check (role in (
    'joint_everyday', 'personal_everyday', 'personal_savings',
    'mortgage', 'credit_card', 'personal_loan', 'other'
  ));

-- Where a manually entered balance came from, so it is obvious in the UI that
-- nobody is syncing it.
alter table accounts
  add column notes text,
  add column balance_updated_by text;

create table analyses (
  id            uuid primary key default gen_random_uuid(),
  kind          text not null default 'periodic'
                check (kind in ('periodic', 'on_demand', 'question', 'expense_plan')),
  -- What was asked, when someone asked something specific.
  question      text,
  -- Exactly what was sent, kept so an answer can always be checked against the
  -- figures it was given.
  snapshot      jsonb not null,
  result        jsonb not null,
  model         text,
  input_tokens  integer,
  output_tokens integer,
  created_at    timestamptz not null default now()
);

create index analyses_created_idx on analyses (created_at desc);
create index analyses_kind_idx on analyses (kind, created_at desc);

create table analyst_settings (
  id           boolean primary key default true check (id),
  -- Off until someone turns it on. Analysis sends financial figures to the
  -- Claude API, so it is never on by surprise.
  enabled      boolean not null default false,
  cadence_days integer not null default 7,
  effort       text not null default 'high' check (effort in ('low', 'medium', 'high', 'xhigh', 'max')),
  last_run_at  timestamptz,
  updated_at   timestamptz not null default now()
);

insert into analyst_settings (id) values (true);

alter table sync_runs
  add column analysis_run boolean not null default false;

insert into schema_migrations (filename) values ('010_analyst_and_manual_accounts.sql') on conflict do nothing;

-- ============================================================
-- 011_assets_and_expected_income.sql
-- ============================================================
-- Levers the forecast could not see: things we could sell, and income we expect
-- but that has not started yet.

-- A motorbike or a PC is not cash, but it is a lever, so the planner should
-- know it exists without it ever counting as spendable.
create table assets (
  id              uuid primary key default gen_random_uuid(),
  name            text not null,
  estimated_value numeric(12,2) not null check (estimated_value >= 0),
  notes           text,
  -- Would we actually sell it. Something we own but would not part with still
  -- belongs on the list, marked so.
  sellable        boolean not null default true,
  sold_on         date,
  sort_order      integer not null default 100,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- Income that is coming but is not in the transaction history yet: a job
-- starting, a side income beginning. The forecast counts it from its start
-- date, so a runway is not pessimistic about money we are confident of.
create table expected_income (
  id           uuid primary key default gen_random_uuid(),
  label        text not null,
  amount       numeric(12,2) not null check (amount > 0),
  cadence_days integer not null check (cadence_days > 0),
  starts_on    date,
  ends_on      date,
  -- How sure we are. The planner treats these differently: a confirmed job is
  -- not the same as one we hope for.
  confidence   text not null default 'likely'
               check (confidence in ('confirmed', 'likely', 'possible')),
  notes        text,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index expected_income_active_idx on expected_income (active, starts_on);

insert into schema_migrations (filename) values ('011_assets_and_expected_income.sql') on conflict do nothing;

-- ============================================================
-- 012_afford_kind.sql
-- ============================================================
-- The affordability planner is its own kind of analysis.
alter table analyses drop constraint if exists analyses_kind_check;
alter table analyses
  add constraint analyses_kind_check check (kind in (
    'periodic', 'on_demand', 'question', 'expense_plan', 'afford'
  ));

insert into schema_migrations (filename) values ('012_afford_kind.sql') on conflict do nothing;

-- ============================================================
-- 013_budget_flows_liquid_only.sql
-- ============================================================
-- Fix: only money moving out of a spendable account is spending.
--
-- The previous rule counted any non transfer row, which swept in everything
-- charged to the mortgage itself: interest, package fees, rate adjustments.
-- Over a year that was about 35,700 dollars of "spending" that never left the
-- household's cash. It inflated the everyday spend rate and made the runway
-- look far shorter than it is.
--
-- Interest on a loan is real, and it does make the household poorer, but it is
-- a change in what is owed rather than cash going out of the door. The forecast
-- is about cash, so it belongs to the debt, not to the budget.
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    -- It has to leave a spendable account at all,
    a.is_liquid
    and (
      -- and either not be a transfer between accounts we own,
      not t.is_transfer
      -- or be one that leaves for a loan, which really is cash gone.
      or not coalesce(pa.is_liquid, true)
    )
  )                           as counts
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id;

insert into schema_migrations (filename) values ('013_budget_flows_liquid_only.sql') on conflict do nothing;

-- ============================================================
-- 014_transport_relabel.sql
-- ============================================================
-- "Transport" read as public transport. It was almost entirely fuel. Relabel
-- so the numbers say what they are, and give public transport its own line.
-- Buckets and the provider map follow by id, so nothing else moves.

update categories set name = 'Getting around', updated_at = now()
 where name = 'Transport' and parent_id is null;

update categories set name = 'Fuel and car', updated_at = now()
 where name = 'Transport' and parent_id is not null;

update categories set name = 'Travel and holidays', updated_at = now()
 where name = 'Travel' and parent_id is not null;

insert into categories (parent_id, name, kind, sort_order)
select g.id, 'Public transport', 'expense', 15
  from categories g
 where g.name = 'Getting around' and g.parent_id is null
on conflict (parent_id, name) do nothing;

-- The one rule worth shipping: the Perth transport card is public transport,
-- not fuel, whatever the bank's category says. Delete it if it is unwanted.
insert into rules (position, name, match_field, match_type, match_value, category_id)
select 5, 'SmartRider is public transport', 'any', 'contains', 'SMARTRIDER', c.id
  from categories c
 where c.name = 'Public transport' and c.parent_id is not null
   and not exists (select 1 from rules where name = 'SmartRider is public transport');

insert into schema_migrations (filename) values ('014_transport_relabel.sql') on conflict do nothing;

-- ============================================================
-- 015_merchants.sql
-- ============================================================
-- Making a bank statement legible.
--
-- A description is full of processor prefixes, store numbers and truncation.
-- merchant_key reduces it to something stable, and merchants holds what we call
-- that place and what it actually is. The key is computed in JavaScript and
-- stored, never recomputed in SQL: one definition, for the same reason
-- matchKeyFor has one.
create table merchants (
  match_key    text primary key,
  -- What to show. Two keys that are really the same place, "The Little Bakery"
  -- and a truncated "The Little Baker", are merged by sharing a display name,
  -- which needs no alias table.
  display_name text not null,
  -- Plain English: what this place is and why money goes there. Filled in by
  -- hand or worked out by Claude.
  what_it_is   text,
  -- Where spending here usually belongs.
  category_id  uuid references categories (id) on delete set null,
  source       text not null default 'auto' check (source in ('auto', 'manual', 'claude')),
  -- Things we consider essential are marked, so the trimming view can put them
  -- aside rather than suggesting the household stop paying for power.
  essential    boolean,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index merchants_display_idx on merchants (display_name);

alter table transactions add column merchant_key text;

create index transactions_merchant_idx on transactions (merchant_key);

insert into schema_migrations (filename) values ('015_merchants.sql') on conflict do nothing;

-- ============================================================
-- 016_merchants_analysis_kind.sql
-- ============================================================
-- Identifying merchants is its own kind of analysis.
alter table analyses drop constraint if exists analyses_kind_check;
alter table analyses
  add constraint analyses_kind_check check (kind in (
    'periodic', 'on_demand', 'question', 'expense_plan', 'afford', 'merchants'
  ));

