-- ============================================================
-- 017_budget_flows_merchant_key.sql
-- ============================================================
-- budget_flows was created before merchant_key existed, and a view does not
-- pick up columns added to its table afterwards. Spending by merchant is a
-- question about flows, so the key belongs on the view rather than every caller
-- joining back to transactions for it.
--
-- The new columns go on the end. create or replace can append to a view but
-- cannot reorder or rename what is already there, so inserting them next to the
-- other transaction fields fails with "cannot change name of view column".
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    a.is_liquid
    and (not t.is_transfer or not coalesce(pa.is_liquid, true))
  )                           as counts,
  t.merchant_name,
  t.merchant_key
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id;

insert into schema_migrations (filename) values ('017_budget_flows_merchant_key.sql') on conflict do nothing;

-- ============================================================
-- 018_prediction_accuracy.sql
-- ============================================================
-- Prediction accuracy: three things the forecast was getting wrong.
--
-- 1. One off spending was setting the rate.
--    The 2025 renovation put about 55,000 dollars through the account over a
--    few months. Hiding it behind a short window was a blunt fix: it also threw
--    away the recent history that makes the rate stable, and it only worked
--    until the next large purchase. Backtesting the estimator against the next
--    60 days of real spending, marking one offs and keeping a longer window
--    beat a short window by about 19 percent. So a transaction can now be
--    marked as a one off. It stays in the history and in every total, because
--    it really happened, and it is excluded only where a rate is worked out.
--
-- 2. Unpaired internal transfers were counted as spending.
--    ING writes the destination account number into the description of a
--    transfer between two of our own accounts. When the other side had not been
--    synced yet, or the destination is not connected, the pair never formed and
--    budget_flows counted the money as gone. It was not gone, it was in the
--    next account along. That was about 710 dollars a month of phantom
--    spending, which shortened the runway for no reason.
--
--    The destination is resolved from the account number in the description
--    instead, so the pair does not have to exist. The liquid rule is unchanged:
--    money moving to another spendable account is not spending, money moving to
--    a loan or a card is.
--
-- 3. There was nowhere to record that a bill is annual.
--    Commitment detection ignores anything with a cadence over 200 days, so
--    rates, rego, insurance and health cover never reached the forecast. They
--    are real and predictable, so they get a flag that lets them be confirmed
--    by hand rather than guessed at from two occurrences.

alter table transactions
  add column if not exists one_off boolean not null default false,
  add column if not exists internal_to_account_id uuid references accounts(id);

comment on column transactions.one_off is
  'Excluded from spend rates and provisions, kept in every total. Set by a person.';
comment on column transactions.internal_to_account_id is
  'Destination account, resolved from the account number in the description when no counterpart row exists.';

create index if not exists transactions_one_off_idx on transactions (one_off) where one_off;

-- Long cadence commitments, confirmed rather than detected. The detector will
-- not create these, so they are never stood down for having gone quiet.
alter table commitments
  add column if not exists annual boolean not null default false;

comment on column commitments.annual is
  'A bill that repeats too rarely for detection to believe in. Entered or confirmed by a person.';

-- budget_flows gains one_off so callers can exclude it from a rate, and starts
-- respecting a resolved internal destination. New columns go on the end:
-- create or replace can append but cannot reorder.
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    -- It has to leave a spendable account at all,
    a.is_liquid
    -- and not be a transfer between accounts we own, whether that was proved
    -- by a matched counterpart or read out of the description,
    and (not t.is_transfer or not coalesce(pa.is_liquid, true))
    and (t.internal_to_account_id is null or not coalesce(ia.is_liquid, false))
  )                           as counts,
  t.merchant_name,
  t.merchant_key,
  t.one_off,
  t.internal_to_account_id
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id
left join accounts ia on ia.id = t.internal_to_account_id;

insert into schema_migrations (filename) values ('018_prediction_accuracy.sql') on conflict do nothing;

-- ============================================================
-- 019_intentions.sql
-- ============================================================
-- Decisions, with a date and a way to check them.
--
-- "We should spend less on takeaway" changes nothing. The research on this is
-- unusually clear: a goal paired with a specific plan for when and where it
-- applies is followed through far more often than the same goal on its own.
-- So a decision made here is stored as a thing, a trigger, and a date, not as
-- a good feeling at the end of a session with the numbers.
--
-- The important column is merchant_key. A tick box records what someone
-- intended. Checking whether the charges actually stopped records what
-- happened. Those are different, and only the second one is worth reporting,
-- so this table is verified against the transactions rather than trusted.
create table if not exists intentions (
  id               uuid primary key default gen_random_uuid(),
  what             text not null,
  -- The "when" half of an implementation intention: the situation that should
  -- trigger the action. "When the renewal email arrives", "before the weekly
  -- shop". Optional, because some decisions are a single act.
  trigger_text     text,
  -- What to watch to see whether it happened. Null when nothing observable
  -- would change, in which case this stays a self reported decision and is
  -- labelled as one.
  merchant_key     text,
  -- What we expect it to be worth per month, for ranking and for honesty about
  -- whether the effort was worth it.
  target_monthly   numeric(12,2),
  starts_on        date not null default current_date,
  review_on        date,
  status           text not null default 'open' check (status in ('open', 'kept', 'slipped', 'dropped')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index if not exists intentions_status_idx on intentions (status, review_on);

-- The household's own goals, so a trade off can be expressed as "this delays
-- the bike by five weeks" rather than as a number of dollars. A dollar is
-- abstract. A date the thing arrives is not.
create table if not exists goals (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  target       numeric(12,2) not null,
  saved        numeric(12,2) not null default 0,
  wanted_by    date,
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

insert into schema_migrations (filename) values ('019_intentions.sql') on conflict do nothing;

-- ============================================================
-- 020_settings.sql
-- ============================================================
-- A small key and value store for household choices that do not deserve a
-- table of their own.
--
-- The first one is the change point: the date the household last changed shape,
-- which is what "did the cut stick" measures from. It can be guessed at from
-- the data, and the guess is usually right, but only a person knows why the
-- spending changed. The guess is a suggestion and the stored value wins, for
-- the same reason the pay cycle is configured rather than inferred.
create table if not exists settings (
  key         text primary key,
  value       text,
  updated_at  timestamptz not null default now()
);

insert into schema_migrations (filename) values ('020_settings.sql') on conflict do nothing;

-- ============================================================
-- 021_debt_vs_living.sql
-- ============================================================
-- Paying down what you owe is not the same as spending it.
--
-- Cash leaving a spendable account for a loan or a card really is cash gone, so
-- it belongs in the runway exactly as it is. But it is not consumption: it buys
-- down a liability rather than buying anything. Lumping the two together makes
-- "going out 17,900 a month" true and useless, because a third of that figure
-- is not a choice anyone makes each month and none of it is trimmable in the
-- way the rest is.
--
-- On this household the split is about 12,500 a month of living and 5,400 a
-- month of debt servicing.
--
-- Two ways a payment is known to be servicing our own debt:
--
--   1. It is a transfer whose far side is one of our non liquid accounts. That
--      already worked, through a matched counterpart or through the account
--      number in the description.
--
--   2. It is paid to a merchant that exists to service one of those accounts:
--      the card issuer, the finance company. Those accounts are entered by hand
--      because open banking cannot reach them, so there is no counterpart row to
--      pair with and the only link is the payee. That link is what
--      merchants.pays_account_id records.
--
-- The savings shuffle is neither of these and stays excluded from everything, as
-- it already was: money moved between two spendable accounts we own has not
-- gone anywhere.
alter table merchants
  add column if not exists pays_account_id uuid references accounts(id);

comment on column merchants.pays_account_id is
  'This payee services that account. Set through the UI, never from a literal in source.';

-- to_own_debt goes on the end: create or replace can append to a view but cannot
-- reorder or rename what is already there.
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    a.is_liquid
    and (not t.is_transfer or not coalesce(pa.is_liquid, true))
    and (t.internal_to_account_id is null or not coalesce(ia.is_liquid, false))
  )                           as counts,
  t.merchant_name,
  t.merchant_key,
  t.one_off,
  t.internal_to_account_id,
  (
    -- Money out, landing on one of our own non liquid accounts.
    t.amount < 0
    and (
      (pa.id is not null and not pa.is_liquid)
      or (ia.id is not null and not ia.is_liquid)
      or (ma.id is not null and not ma.is_liquid)
    )
  )                           as to_own_debt
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id
left join accounts ia on ia.id = t.internal_to_account_id
left join merchants mm on mm.match_key = t.merchant_key
left join accounts ma on ma.id = mm.pays_account_id;

insert into schema_migrations (filename) values ('021_debt_vs_living.sql') on conflict do nothing;

-- ============================================================
-- 022_account_identity.sql
-- ============================================================
-- An account is identified by its number at its bank, not by a Redbark id.
--
-- Relinking a connection, which happens whenever consent is renewed and CDR
-- consent expires every twelve months, issues brand new account ids for every
-- account behind it. Adding the personal loan to the ING connection did exactly
-- that: all four ING accounts came back with ids we had never seen.
--
-- upsertAccounts only knew how to conflict on redbark_account_id, so that would
-- have inserted four new accounts and left the originals orphaned, still
-- holding every transaction, every balance, and the is_liquid and role settings
-- that the whole forecast depends on. Spendable cash would have been read off
-- the new empty rows. Nothing would have errored.
--
-- The stable identity is the institution plus the masked number, so that is
-- what gets the unique index. A manually created account can then be adopted by
-- the connection that later starts serving it, keeping its balance and its role,
-- which is what happened to the personal loan here.
--
-- Partial, because accounts entered by hand for debts open banking cannot reach
-- have no masked number at all and several of them would otherwise collide on
-- null.
create unique index if not exists accounts_bank_number_idx
  on accounts (bank, masked_number)
  where masked_number is not null;

insert into schema_migrations (filename) values ('022_account_identity.sql') on conflict do nothing;

-- ============================================================
-- 023_reversals.sql
-- ============================================================
-- A charge that was refunded is not spending, and its refund is not income.
--
-- Real statements carry reversals: a contractor charged 1,419 dollars and
-- refunded it the same day, a subscription double billed and gave one back, a
-- card investigation reversed a disputed charge. Both halves were being counted.
-- The charge went into spending because it is a negative amount leaving a
-- spendable account, and the refund came back as "Other income" because the
-- provider categorises an unexplained credit that way. So a payment that never
-- really happened inflated spending AND income by the same amount, and the
-- household's biggest single "merchandise" merchant was a reversal.
--
-- This is the transfer problem again, in a different costume, so it gets the
-- same answer: pair the two sides and let budget_flows exclude the pair. That
-- needs no change at the twenty four places that filter on amount, because they
-- all go through counts already.
--
-- Pairing is deliberately strict. Same merchant, same amount to the cent,
-- refund on or after the charge and within thirty days, and each row used once.
-- A positive amount that finds no charge to cancel is left exactly as it was: it
-- might be a rebate, a cashback, or money someone sent us, and guessing is worse
-- than leaving it alone.
alter table transactions
  add column if not exists reversal_of_id uuid references transactions(id);

comment on column transactions.reversal_of_id is
  'This credit cancels that charge. Both sides stop counting as spending or income.';

create index if not exists transactions_reversal_of_idx on transactions (reversal_of_id)
  where reversal_of_id is not null;

-- counts gains one more condition: neither side of a reversal counts. The new
-- column goes on the end, since create or replace can append but not reorder.
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    a.is_liquid
    and (not t.is_transfer or not coalesce(pa.is_liquid, true))
    and (t.internal_to_account_id is null or not coalesce(ia.is_liquid, false))
    -- Not the credit that cancels a charge,
    and t.reversal_of_id is null
    -- and not the charge that a credit cancelled.
    and not exists (select 1 from transactions r where r.reversal_of_id = t.id)
  )                           as counts,
  t.merchant_name,
  t.merchant_key,
  t.one_off,
  t.internal_to_account_id,
  (
    t.amount < 0
    and (
      (pa.id is not null and not pa.is_liquid)
      or (ia.id is not null and not ia.is_liquid)
      or (ma.id is not null and not ma.is_liquid)
    )
  )                           as to_own_debt,
  t.reversal_of_id
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id
left join accounts ia on ia.id = t.internal_to_account_id
left join merchants mm on mm.match_key = t.merchant_key
left join accounts ma on ma.id = mm.pays_account_id;

insert into schema_migrations (filename) values ('023_reversals.sql') on conflict do nothing;

-- ============================================================
-- 024_merchant_ended.sql
-- ============================================================
-- A cost that has been cancelled should stop being forecast.
--
-- The household changed insurers. Six Youi policies worth about 614 a month are
-- still in the window, so the spend rate still expects them, and the forecast
-- will keep expecting them for as long as the window remembers. Nothing is
-- wrong with the history: those payments really happened. What is wrong is
-- treating them as a guide to next month, which is the same distinction
-- transactions.one_off already makes, but about a merchant rather than a
-- purchase, and about everything it charges from here on rather than one row.
--
-- The same thing is needed every time a subscription is cancelled, a gym is
-- quit, or a service is switched, and a decision on the Today page that is
-- verified as held is exactly this. Waiting for commitment detection to stand
-- it down takes two full cycles, which is two months of a forecast that is
-- knowably wrong.
alter table merchants
  add column if not exists ended_on date;

comment on column merchants.ended_on is
  'No longer expected from this date. Kept in history and in every total, left out of any rate.';

-- budget_flows gains one flag for it. New column on the end: create or replace
-- can append but cannot reorder.
create or replace view budget_flows as
select
  t.id,
  t.account_id,
  t.txn_date,
  t.posted_date,
  t.amount,
  t.status,
  t.description,
  t.display_description,
  t.category_id,
  t.is_transfer,
  t.transfer_pair_id,
  a.is_liquid                 as from_liquid,
  pa.is_liquid                as to_liquid,
  (
    a.is_liquid
    and (not t.is_transfer or not coalesce(pa.is_liquid, true))
    and (t.internal_to_account_id is null or not coalesce(ia.is_liquid, false))
    and t.reversal_of_id is null
    and not exists (select 1 from transactions r where r.reversal_of_id = t.id)
  )                           as counts,
  t.merchant_name,
  t.merchant_key,
  t.one_off,
  t.internal_to_account_id,
  (
    t.amount < 0
    and (
      (pa.id is not null and not pa.is_liquid)
      or (ia.id is not null and not ia.is_liquid)
      or (ma.id is not null and not ma.is_liquid)
    )
  )                           as to_own_debt,
  t.reversal_of_id,
  -- True once the merchant has been marked as finished with. Kept out of rates,
  -- never out of history.
  (mm.ended_on is not null)   as no_longer_expected
from transactions t
join accounts a on a.id = t.account_id
left join transactions p on p.id = t.transfer_pair_id
left join accounts pa on pa.id = p.account_id
left join accounts ia on ia.id = t.internal_to_account_id
left join merchants mm on mm.match_key = t.merchant_key
left join accounts ma on ma.id = mm.pays_account_id;

insert into schema_migrations (filename) values ('024_merchant_ended.sql') on conflict do nothing;

commit;
